def _get_default_gpu_device_type() -> str:
    avail_gpus = [
        device_type
        for device_type in GPU_BENCHMARK_DEVICE_TYPES
        if getattr(torch, device_type).is_available()
    ]
    assert len(avail_gpus) <= 1
    return "cuda" if len(avail_gpus) == 0 else avail_gpus.pop()

def _normalize_gpu_device_type(device_type: str | torch.device | None) -> str:
    if device_type is None:
        return _get_default_gpu_device_type()
    if isinstance(device_type, torch.device):
        return device_type.type
    return torch.device(device_type).type

class Benchmarker:
    """
    A device-agnostic benchmarking utility for measuring the runtime of
    inductor generated callables.
    """

    def __init__(self: Self) -> None:
        pass

    def infer_device(self, *fn_args: Any, **fn_kwargs: Any) -> torch.device:
        inferred_device: torch.device | None = None
        for arg_or_kwarg in chain(fn_args, fn_kwargs.values()):
            # Some callables take nested structures as arguments so use the
            # flattened form to find any tensors
            for arg_or_kwarg_leaf in pytree.tree_leaves(arg_or_kwarg):
                if not isinstance(arg_or_kwarg_leaf, torch.Tensor):
                    continue
                if inferred_device is None:
                    inferred_device = arg_or_kwarg_leaf.device
                elif arg_or_kwarg_leaf.device != inferred_device:
                    raise ValueError(
                        "Can't safely infer the device type of `fn` with multiple device types in `fn_args` and `fn_kwargs`!"
                    )

        if inferred_device is None:
            raise ValueError(
                "Can't safely infer the device type of `fn` with no device types"
                " in `fn_args` or `fn_kwargs`. Use a direct benchmarking method instead e.g. "
                "`Benchmarker.benchmark_cpu` or `Benchmarker.benchmark_gpu`."
            )

        return inferred_device

    @time_and_count
    def benchmark(
        self: Self,
        fn: Callable[..., Any],
        fn_args: tuple[Any, ...] | None = None,
        fn_kwargs: dict[str, Any] | None = None,
        device: str | torch.device | None = None,
        **kwargs: Any,
    ) -> float:
        """Benchmark `fn(*fn_args, *fn_kwargs)` and return the runtime, in milliseconds (the
        actual runtime calculation is dictated by the benchmarking implementation, but may be
        one of [mean, median, minimum, etc.]). Functions as a convenience wrapper around
        device-specific implementations, like `benchmark_cpu` and `benchmark_gpu`. Raises
        `ValueError(...)` if we can't safely infer the device type of `fn`; for example,
        if multiple device types are found in `fn_args` and `fn_kwargs`, or if no device
        types are found. To bypass device inference, provide the device to the `device`
        parameter.

        WARNING: if `fn` mutates `fn_args` or `fn_kwargs`, benchmarking may fail unexpectedly.
        For example, if `fn` clears a mutable object, subsequent invocations of `fn` during
        benchmarking will fail. In such cases, `fn` should handle cloning its arguments internally.
        If device inference is required, `Benchmarker.infer_device` can be used prior to calling
        this method without any arguments for `fn_args` and `fn_kwargs`.

        Arguments:
        - fn: The function to benchmark.
        - fn_args: The function's arguments.
        - fn_kwargs: The function's kwargs.

        Keyword Arguments:
        - device: Which device to use for benchmarking. If not provided the device will be attempted
        to be inferred from `fn_args` and `fn_kwargs`.
        - **kwargs: The benchmarking implementation's kwargs.

        Returns:
        - The runtime of `fn(*fn_args, **fn_kwargs)`, in milliseconds.
        """
        inferred_device: torch.device | None = None
        if device is not None:
            inferred_device = (
                torch.device(device) if isinstance(device, str) else device
            )
        else:
            if fn_args is None and fn_kwargs is None:
                raise ValueError(
                    "`fn_args` and `fn_kwargs` cannot both be None if `device` is not provided."
                )

            fn_args = fn_args or tuple()
            fn_kwargs = fn_kwargs or {}
            inferred_device = self.infer_device(*fn_args, **fn_kwargs)

        assert isinstance(inferred_device, torch.device)

        fn_args = fn_args or tuple()
        fn_kwargs = fn_kwargs or {}

        # No need to wrap if the callable takes no arguments
        if len(fn_args) == 0 and len(fn_kwargs) == 0:
            # Keep a true zero-arg callable type to satisfy type checkers.
            def _callable() -> Any:
                return fn()
        else:
            _args = fn_args
            _kwargs = fn_kwargs

            def _callable() -> Any:
                return fn(*_args, **_kwargs)

        warmup = kwargs.pop("warmup", inductor_config.inductor_default_autotune_warmup)
        rep = kwargs.pop("rep", inductor_config.inductor_default_autotune_rep)

        # Surfacing all kernels during autotuning is super noisy; filtering these out.
        with DebugMode._benchmarking_inductor():
            # First, try a registered device-specific benchmarker
            benchmark_fn: Callable[..., Any] | None = _BENCHMARK_DISPATCH.get(
                inferred_device.type
            )
            if benchmark_fn is not None:
                return benchmark_fn(self, _callable, warmup=warmup, rep=rep, **kwargs)

            # Backward-compatible default:
            # - CPU  -> CPU benchmark path
            # - else -> GPU benchmark path (legacy behavior retained for non-CPU)
            if inferred_device == torch.device("cpu"):
                return self.benchmark_cpu(_callable, warmup=warmup, rep=rep, **kwargs)
            return self.benchmark_gpu(_callable, warmup=warmup, rep=rep, **kwargs)

    @time_and_count
    def benchmark_cpu(
        self: Self, _callable: Callable[[], Any], warmup: int = 20, rep: int = 100
    ) -> float:
        """Benchmark the CPU callable, `_callable`, and return the median runtime,
        in milliseconds.

        Arguments:
        - _callable: The CPU callable to benchmark.

        Keyword Arguments:
        - warmup: Optionally, the duration, in milliseconds, to run `_callable`
        before benchmarking starts.
        - rep: Optionally, the duration, in milliseconds, to run `_callable`
        during benchmarking.

        Returns:
        - The median runtime of `_callable`, in milliseconds.
        """

        def run_for(ms: int) -> list[float]:
            timings = []
            run_start_t = time.perf_counter()
            while True:
                start_t = time.perf_counter()
                _callable()
                end_t = time.perf_counter()
                timings.append((end_t - start_t) * MILLISECONDS_PER_SECOND)
                if ((end_t - run_start_t) * MILLISECONDS_PER_SECOND) > ms:
                    break
            return timings

        run_for(warmup)
        return median(run_for(rep))

    @time_and_count
    def benchmark_gpu(self: Self, *args: Any, **kwargs: Any) -> float:
        raise NotImplementedError

    @time_and_count
    @gpu_benchmark_lock
    def benchmark_gpu_with_cuda_graph(
        self: Self,
        _callable: Callable[[], Any],
        **kwargs: Any,
    ) -> float:
        """Benchmark a GPU callable using CUDA graph capture and replay.

        This captures the callable into a CUDA graph and benchmarks the graph replay,
        which eliminates kernel launch overhead for fair comparison between different
        implementations.
        """
        # Warmup
        _callable()
        torch.cuda.synchronize()

        # Capture into CUDA graph
        cuda_graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(cuda_graph, capture_error_mode="thread_local"):
            _callable()
        torch.cuda.synchronize()

        return self.benchmark_gpu(cuda_graph.replay, **kwargs)

class _LoweringSerializer:
    """
    This handles the data for serializing lowering.lowering
    """

    # A full implementation would make sure that all lowerings are copied over
    # (or at least detected and raise a bypass when a non-standard lowering is
    # used). For now we just handle tests by looking for lowerings that were
    # overridden with a forced fallback.
    fallbacks: OrderedSet[str]

    def __init__(self) -> None:
        from . import lowering

        self.fallbacks = OrderedSet(
            str(k) for k, v in lowering.lowerings.items() if _is_fallback_handler(v)
        )

    def patch(self) -> _LoweringSerializerContextManager:
        return _LoweringSerializerContextManager(self)

class _LoweringSerializerContextManager(contextlib.ExitStack):
    """
    Helper for _LoweringSerializer.patch()
    """

    def __init__(self, lowering: _LoweringSerializer) -> None:
        super().__init__()
        self.lowering = lowering

    @override
    def __enter__(self) -> Self:
        super().__enter__()

        from . import lowering

        for k, v in lowering.lowerings.items():
            name = str(k)
            if name in self.lowering.fallbacks:
                if not _is_fallback_handler(v):
                    self.enter_context(lowering.force_fallback(k))  # type: ignore[arg-type]

        return self

def _bench_with_launch_args(self, launcher, launch_args, reset_args, **kwargs):
    device_interface = self.get_device_interface()
    stream = device_interface.get_raw_stream(device_interface.current_device())

    def kernel_call():
        cloned_args, cloned_kwargs = self.clone_args(*launch_args, **kwargs)
        self.reset_to_zero_args(*reset_args, **kwargs)
        launcher(
            *cloned_args,
            **cloned_kwargs,
            stream=stream,
        )

    if (
        self.inductor_meta.get("profile_bandwidth_with_do_bench_using_profiling", False)
        and not npu_profiler_session_active()
    ):
        return do_bench_using_profiling_npu(kernel_call, rep=1)

    return benchmarker.benchmark_gpu(kernel_call, rep=1, device_type='npu')

def dtype_optimal_pass(graph: torch.fx.Graph) -> None:
    """Narrow unnecessary int64 to int32: if the values of torch.arange or to(int64)
    fit safely in int32, downgrade the dtype to cut memory traffic and compute cost."""
    cast_dtype_limit = [torch.float32, torch.int32, torch.bool, torch.int16, torch.int8]
    changed = False
    for node in list(graph.nodes):  # use list to avoid mutating while iterating
        if (
            node.op == "call_function"
            and node.target == torch.arange
            and node.kwargs.get("dtype", None) == torch.int64
        ):
            # step 1: extract start/end/step dynamically (handles different args lengths)
            args_len = len(node.args)
            start = 0
            end = None
            step = 1
            if args_len == 1:
                end = node.args[0]  # arange(end)
            elif args_len == 2:
                start = node.args[0]
                end = node.args[1]  # arange(start, end)
            elif args_len >= 3:
                start = node.args[0]
                end = node.args[1]
                step = node.args[2]  # arange(start, end, step)
            # merge kwargs overrides (e.g. a user-specified kwargs['start'])
            start = node.kwargs.get("start", start)
            end = node.kwargs.get("end", end)
            step = node.kwargs.get("step", step)
            # if end is None, treat it as unbounded and skip (rare, but safe)
            if end is None:
                continue
            # Normalize start/end/step (symbolic allowed); elements always lie in
            # [start, end), so downgrade is safe once both bounds provably fit int32; step must be a nonzero int.
            r_start = resolve_size_arg(start)
            r_end = resolve_size_arg(end)
            r_step = resolve_size_arg(step)
            if r_start is None or r_end is None or r_step is None:
                continue
            if not isinstance(r_step, int) or r_step == 0:
                continue
            if statically_fits_int32(r_start, r_end):
                node.kwargs = {**node.kwargs, "dtype": torch.int32}
                changed = True
        if node.op == "call_method":
            input_node = node.args[0]
            input_fake = (
                input_node.meta.get("example_value", None)
                if hasattr(input_node, "meta")
                else None
            )
            input_dtype = input_fake.dtype if input_fake is not None else None
            target_dtype = (
                node.args[1] if len(node.args) > 1 else node.kwargs.get("dtype", None)
            )
            if (
                input_dtype in cast_dtype_limit
                and node.target == "to"
                and target_dtype == torch.int64
            ):
                if len(node.args) > 1:
                    node.args = (node.args[0], torch.int32)  # update the positional dtype
                else:
                    node.kwargs = {
                        **node.kwargs,
                        "dtype": torch.int32,
                    }  # update the kwargs dtype
                changed = True
    eliminate_dead_code(graph, changed, dtype_optimal_pass.__name__, False)

def copy_tests(my_cls, other_cls, suffix, test_failures=None, xfail_prop=None):
    for name, value in my_cls.__dict__.items():
        if name.startswith("test_"):
            # You cannot copy functions in Python, so we use closures here to
            # create objects with different ids. Otherwise, unittest.skip
            # would modify all methods sharing the same object id. Also, by
            # using a default argument, we create a copy instead of a
            # reference. Otherwise, we would lose access to the value.

            @functools.wraps(value)
            def new_test(self, value=value):
                return value(self)

            # Copy __dict__ which may contain test metadata
            new_test.__dict__ = copy.deepcopy(value.__dict__)

            if xfail_prop is not None and hasattr(value, xfail_prop):
                new_test = unittest.expectedFailure(new_test)

            tf = test_failures and test_failures.get(name)
            if tf and suffix in tf.suffixes:
                skip_func = (
                    unittest.skip("Skipped!")
                    if tf.is_skip
                    else unittest.expectedFailure
                )
                new_test = skip_func(new_test)

            setattr(other_cls, f"{name}_{suffix}", new_test)

    # Special case convenience routine
    if hasattr(my_cls, "is_dtype_supported"):
        other_cls.is_dtype_supported = my_cls.is_dtype_supported

@impl(m, "npu_gather_backward")
def npu_gather_backward__meta(grad, self_size, dim, index, sparse_grad):
    if sparse_grad:
        self_dim = len(self_size)
        if self_dim == 0:
            return torch.sparse_coo_tensor(
                torch.empty((0, grad.numel()), dtype=index.dtype, device=grad.device),
                grad,
                self_size,
                device=grad.device,
            )
        if grad.dim() == 0:
            return torch.sparse_coo_tensor(
                index.view(1, 1),
                grad,
                self_size,
                device=grad.device,
            )

        sparse_ind = torch.empty((self_dim, grad.numel()), dtype=torch.long, device=grad.device)
        grad_numel = grad.numel()
        if grad_numel > 0:
            n_above = grad_numel
            n_below = 1
            if dim < 0:
                dim += self_dim
            for i in range(self_dim):
                n_above //= grad.size(i)
                if i == dim:
                    sparse_ind[i] = index.reshape(-1)
                else:
                    sparse_ind[i] = (
                        torch.arange(grad.size(i), dtype=torch.long, device=grad.device)
                        .unsqueeze(1)
                        .expand(grad.size(i), n_above)
                        .reshape(-1)
                        .repeat(n_below)
                    )
                n_below *= grad.size(i)
        return torch.sparse_coo_tensor(
            sparse_ind,
            grad.reshape(-1),
            self_size,
            device=grad.device,
        )
    return torch.empty(self_size, dtype=grad.dtype, device=grad.device)

@register_decomposition(aten._to_copy)
@out_wrapper()
def _to_copy(
    x: Tensor | NumberType,
    *,
    dtype: torch.dtype | None = None,
    layout=None,
    device: torch.device | None = None,
    pin_memory: bool = False,
    non_blocking: bool = False,
    memory_format: torch.memory_format | None = None,
):
    if layout and layout != torch.strided:
        raise AssertionError(f"layout must be None or torch.strided, got {layout}")
    if pin_memory:
        raise AssertionError(
            "pin_memory=True is not supported in _to_copy decomposition"
        )
    if not isinstance(x, (torch.Tensor, int, float, bool, complex)):
        raise AssertionError(f"x must be Tensor or scalar, got {type(x).__name__}")
    if device is None and dtype is None and memory_format is None:
        if isinstance(x, torch.Tensor):
            return x.clone()
        else:
            return x
    dtype_converted = False

    if isinstance(x, torch.Tensor):
        x_tensor = x
    else:
        x_tensor = torch.scalar_tensor(x)

    if device is not None and device != x_tensor.device:
        # When both dtype and device change, decide where to do the dtype
        # conversion.  The general heuristic is to convert on the faster
        # device (i.e. avoid conversions on cpu when the source is a gpu).
        # However, we must convert on the *source* device when the target
        # device does not support the source dtype – e.g. copying a float64
        # tensor to an XPU device that lacks fp64 hardware would otherwise
        # create an unsupported intermediate buffer on the target device.
        if dtype is not None:
            convert_before_transfer = False
            if device.type == "cpu":
                # Source is accelerator, target is CPU – convert on the
                # (faster) source device before the transfer.
                convert_before_transfer = True
            elif x_tensor.dtype == torch.float64:
                # The target device may not support float64 (e.g. Intel Arc
                # consumer GPUs).  Convert to the requested dtype on the
                # source device to avoid creating an unsupported fp64
                # intermediate buffer on the target device.
                from torch._inductor.utils import device_supports_fp64

                if not device_supports_fp64(device):
                    convert_before_transfer = True

            if convert_before_transfer:
                x_tensor = torch._prims.convert_element_type(x_tensor, dtype)
                dtype_converted = True
        x_tensor = torch._prims.device_put(x_tensor, device, non_blocking)

    if dtype is not None and not dtype_converted:
        x_tensor = torch._prims.convert_element_type(x_tensor, dtype)
        dtype_converted = True

    if memory_format is not None:  # no ref/prim for memory format
        return torch.clone(x_tensor, memory_format=memory_format)
    return x_tensor

def _device_put_aten(
    a: Tensor, device: str | torch.device, non_blocking=False
) -> Tensor:
    return a.to(device, non_blocking=non_blocking)

def highest_precision_float(device):
