        return torch.float32
    else:
        return torch.float64

@core.extern
def pow(arg0, arg1, _semantic=None):
    """
    Power function, computes x raised to the power of y.

    :param arg0: ``x``. Supported dtype(s): ``float32``.
    :type arg0: scalar or tl.tensor
    :param arg1: ``y``. Supported dtype(s): ``float32``.
    :type arg1: scalar or tl.tensor
    :return: x raised to the power of y.
    :rtype: ``float32``
    """
    arg0 = _semantic.to_tensor(arg0)
    arg1 = _semantic.to_tensor(arg1)
    if arg1.dtype == core.dtype("int32"):
        arg1 = _semantic.cast(arg1, arg0.dtype)

    if arg0.dtype == core.dtype("fp32") and _is_a5_target(_semantic):
        return core.extern_elementwise(
            "", "", [arg0, arg1], {
                (core.dtype("fp32"), core.dtype("fp32")): ("__hmf_pow_fp32", core.dtype("fp32")),
                (core.dtype("fp32"), core.dtype("int32")): ("__hmf_powi_fp32", core.dtype("fp32")),
            }, is_pure=True, _semantic=_semantic)
    return core.extern_elementwise(
        "", "", [arg0, arg1], {
            (core.dtype("fp32"), core.dtype("fp32")): ("__hmf_powf", core.dtype("fp32")),
            (core.dtype("fp16"), core.dtype("fp16")): ("__hmf_powDh", core.dtype("fp16")),
            (core.dtype("bf16"), core.dtype("bf16")): ("__hmf_powDb", core.dtype("bf16")),
        }, is_pure=True, _semantic=_semantic)

import torch,torch_npu,inspect,json
from torch_npu.contrib import transfer_to_npu
import torch_npu._inductor

torch.npu.set_device(1)
wrapped=torch.tensor
original=inspect.unwrap(wrapped)
rows=[]
for label,ctor in [('wrapped',wrapped),('unwrapped',original)]:
    for kind in ['sum_tolist','nonzero_index']:
        def fn(x):
            if kind=='sum_tolist':
                return ctor(sum(x.tolist()))
            n=torch.nonzero(x).size(0)
            return torch.index_select(x,0,ctor([1,n-5],device='npu:1'))
        x=torch.randint(1,10,(32,),device='npu:1')
        torch._dynamo.reset()
        row={'constructor':label,'case':kind,'backend':'eager (Dynamo isolation)'}
        try:
            with torch._dynamo.config.patch(capture_scalar_outputs=True,capture_dynamic_output_shape_ops=True):
                actual=torch.compile(fn,backend='eager',fullgraph=True)(x)
            row.update(status='passed',equal=torch.equal(actual,fn(x)))
        except Exception as e:
            row.update(status='failed',error_type=type(e).__name__,error=str(e).split('For more information')[0][:900])
        rows.append(row)
print('PROBE_JSON='+json.dumps({'same_constructor':original is wrapped,'rows':rows}))

def _has_sufficient_memory(device, size):
    device_ = torch.device(device)
    device_type = device_.type
    if device_type in ["cuda", "xpu"]:
        acc = torch.accelerator.current_accelerator()
        # Case 1: no accelerator found
        if not acc:
            return False
        # Case 2: accelerator found but not matching device type
        if acc.type != device_type:
            return True
        # Case 3: accelerator found and matching device type but not available
        if not torch.accelerator.is_available():
            return False
        # Case 4: accelerator found and matching device type and available
        gc.collect()
        torch.accelerator.empty_cache()

        if device_.index is None:
            device_ = torch.device(device_type, 0)

        if device_type == "cuda":
            return (
                torch.cuda.memory.mem_get_info(device_)[0]
                * torch.cuda.memory.get_per_process_memory_fraction(device_)
            ) >= size

        if device_type == "xpu":
            return torch.xpu.memory.mem_get_info(device_)[0] >= size

    if device_type == "xla":
        raise unittest.SkipTest("TODO: Memory availability checks for XLA?")

    if device_type not in ["cpu", "mps"]:
        raise unittest.SkipTest("Unknown device type")

    # CPU
    if not HAS_PSUTIL:
        raise unittest.SkipTest("Need psutil to determine if memory is sufficient")

    # The sanitizers have significant memory overheads
    if TEST_WITH_ASAN or TEST_WITH_TSAN or TEST_WITH_UBSAN:
        effective_size = size * 10
    else:
        effective_size = size

    # don't try using all RAM on s390x, leave some for service processes
    if IS_S390X:
        effective_size = effective_size * 2

    if psutil.virtual_memory().available < effective_size:
        gc.collect()
    return psutil.virtual_memory().available >= effective_size

def largeTensorTest(size, device=None, inductor=TEST_WITH_TORCHINDUCTOR):
    """Skip test if the device has insufficient memory to run the test

    size may be a number of bytes, a string of the form "N GB", or a callable

    If the test is a device generic test, available memory on the primary device will be checked.
    It can also be overridden by the optional `device=` argument.
    In other tests, the `device=` argument needs to be specified.
    """
    if isinstance(size, str):
        if not size.endswith(("GB", "gb")):
            raise AssertionError(f"only bytes or GB supported, got {size!r}")
        size = 1024**3 * int(size[:-2])

    def inner(fn):
        @wraps(fn)
        def dep_fn(self, *args, **kwargs):
            size_bytes: int = size(self, *args, **kwargs) if callable(size) else size
            _device = device
            if _device is None:
                if hasattr(self, "get_primary_device"):
                    _device = self.get_primary_device()
                else:
                    _device = self.device

            # If this is running with GPU cpp_wrapper, the autotuning step will generate
            # an additional array of the same size as the input.
            if inductor and torch._inductor.config.cpp_wrapper and _device != "cpu":
                size_bytes *= 2
            if not _has_sufficient_memory(_device, size_bytes):
                raise unittest.SkipTest(f"Insufficient {_device} memory")

            return fn(self, *args, **kwargs)

        return dep_fn

    return inner

void NpuP2pCtrl::enable_peer_access(int32_t source_dev, int32_t dest_dev) {
  uint32_t enable_flag_value = 0;
  c10_npu::NPUGuard guard(source_dev);
  NPU_CHECK_ERROR(aclrtDeviceEnablePeerAccess(dest_dev, enable_flag_value));
  return;
}

// Check whether the two devices are enabled by p2p and tensor can be copied
bool NpuP2pCtrl::get_p2p_access(int32_t source_dev, int32_t dest_dev, bool& flag) {
  TORCH_INTERNAL_ASSERT(num_devices_ >= 0, "p2p access cache not initialized");
  TORCH_CHECK(source_dev >= 0 && source_dev < num_devices_, source_dev, " is not a device", PTA_ERROR(ErrCode::VALUE));
  TORCH_CHECK(dest_dev >= 0 && dest_dev < num_devices_, dest_dev, " is not a device", PTA_ERROR(ErrCode::VALUE));

  // get access source_dev -> dest_dev
  auto& cache_s2d = p2p_access_enabled_cache_[source_dev * num_devices_ + dest_dev];
  auto& cache_d2s = p2p_access_enabled_cache_[dest_dev * num_devices_ + source_dev];

  if (cache_s2d != P2pStatus::UNKNOWN) {
    return static_cast<bool>(cache_s2d);
  }

  // update: this limitation no longer exists in the A3 and later soc version
  if (c10_npu::GetSocVersion() < c10_npu::SocVersion::Ascend910_9391) {
    int32_t limited_device = -1;
    // check whether the connection limit of the source or destination device
    // has been reached.
    if (device_enabled_count_[source_dev] >= C10_P2P_ACCESS_MAX_NPUS) {
      limited_device = source_dev;
    } else if (device_enabled_count_[dest_dev] >= C10_P2P_ACCESS_MAX_NPUS) {
      limited_device = dest_dev;
    }

    if (limited_device != -1) {
      cache_s2d = P2pStatus::COPY_NOT_ALLOWED;
      cache_d2s = P2pStatus::COPY_NOT_ALLOWED;

      std::string warning_str{};
      for (auto i = 0; i < num_devices_; i++) {
        if (i == limited_device) {
          continue;
        }
        if (p2p_access_enabled_cache_[limited_device * num_devices_ + i] == P2pStatus::COPY_ALLOWED) {
          warning_str += std::to_string(i);
          warning_str += ", ";
        }
      }
      ASCEND_LOGE(
          "Device %d has reached P2P connection limit %d. Current connections: [%s]. "
          "Cannot enable P2P between devices (%d and %d). ",
          limited_device,
          C10_P2P_ACCESS_MAX_NPUS,
          warning_str.c_str(),
          source_dev,
          dest_dev);
      return static_cast<bool>(cache_s2d);
    }
  }

  ASCEND_LOGW("The NPU device is %d, and try to copy and enable p2p with %d. ", source_dev, dest_dev);

  // The aclrtEnablePeerAccess capability is not equal to cuda,
  // And both sides need to be enabled to activate the p2p capability
  int32_t result_s2d = -1;
  int32_t result_d2s = -1;
  NPU_CHECK_ERROR(aclrtDeviceCanAccessPeer(&result_s2d, source_dev, dest_dev));
  NPU_CHECK_ERROR(aclrtDeviceCanAccessPeer(&result_d2s, dest_dev, source_dev));
  // A two-way enable is required
  if (!result_s2d || !result_d2s) {
    cache_s2d = P2pStatus::COPY_NOT_ALLOWED;
    cache_d2s = P2pStatus::COPY_NOT_ALLOWED;
    flag = true;
    return static_cast<bool>(cache_s2d);
  }

  enable_peer_access(source_dev, dest_dev);
  enable_peer_access(dest_dev, source_dev);
  // A two-way enable is required
  cache_s2d = P2pStatus::COPY_ALLOWED;
  cache_d2s = P2pStatus::COPY_ALLOWED;
  // Update p2p enable count
  device_enabled_count_[source_dev]++;
  device_enabled_count_[dest_dev]++;

  return static_cast<bool>(cache_s2d);
}
